18	// secretPattern matches high-entropy strings that may be secrets.
19	// Note: / is excluded to prevent matching entire file paths as single tokens.
20	// Base64 and JWT tokens are still caught via high-entropy segments between slashes.
21	var secretPattern = regexp.MustCompile(`[A-Za-z0-9+_=-]{10,}`)
22	
23	// credentialedURIPattern matches URLs that embed userinfo with a password, such
24	// as REDACTED or REDACTED These often have
25	// moderate entropy and are not reliably covered by vendor-specific scanners.
26	var credentialedURIPattern = regexp.MustCompile(`(?i)\b[a-z][a-z0-9+.-]{1,31}://[^\s/?#@"'` + "`" + `<>:]*:[^\s/?#@"'` + "`" + `<>]+@[^\s"'` + "`" + `<>]+`)
27	
28	// dbPasswordKeyShape matches a DB-prefixed credential key (vendor prefix +
29	// optional `_word`/`-word` segments + `password`/`passwd`/`pwd`). Used to
30	// compose both the env-var assignment regex and the JSON-key regex so the
31	// vendor list stays in one place.
32	const dbPasswordKeyShape = `(?:db|database|pg|postgres|postgresql|mysql|mariadb|redis|mongo|mongodb|sqlserver|mssql|jdbc)(?:[_-]+[a-z0-9]+)*[_-]*(?:password|passwd|pwd)` //nolint:gosec // regex literal, not a credential
33	
34	var (
35		jdbcPattern          = regexp.MustCompile(`(?i)\bjdbc:[^\s"'<>` + "`" + `]+`)
36		databaseURLPattern   = regexp.MustCompile(`(?i)\b(?:postgres(?:ql)?|mysql|mariadb|mongodb(?:\+srv)?|redis)://[^\s"'<>` + "`" + `]+`)
37		keywordDSNPattern    = regexp.MustCompile(`(?i)\b[a-z_][a-z0-9_]*=(?:"[^"]*"|'[^']*'|[^\s"']+)(?:\s+[a-z_][a-z0-9_]*=(?:"[^"]*"|'[^']*'|[^\s"']+)){2,}`)
38		semicolonConnPattern = regexp.MustCompile(`(?i)\b[a-z][a-z0-9 _-]*=(?:\{[^}]*\}|"[^"]*"|'[^']*'|[^=;"'\s]+)(?:;[a-z][a-z0-9 _-]*=(?:\{[^}]*\}|"[^"]*"|'[^']*'|[^=;"'\s]+)){2,}`)
39		// credentialValuePattern requires the prefix to start at a non-alphanumeric
40		// boundary, so APP_DB_PASSWORD matches via the leading `_` but mydbpassword
41		// does not.
42		credentialValuePattern = regexp.MustCompile(`(?i)(?:^|[^A-Za-z0-9])(` + dbPasswordKeyShape + `)\s*=\s*("[^"]*"|'[^']*'|[^\s,;&]+)`)
43	
44		keywordHostPattern      = regexp.MustCompile(`(?i)(?:^|\s)host=`)
45		keywordUserPattern      = regexp.MustCompile(`(?i)(?:^|\s)user=`)
46		semicolonServerPattern  = regexp.MustCompile(`(?i)(?:^|;)\s*(?:server|data source|datasource|addr|address|network address)\s*=`)
47		semicolonUserPattern    = regexp.MustCompile(`(?i)(?:^|;)\s*(?:user id|userid|user|uid)\s*=`)
48		passwordAssignmentRegex = regexp.MustCompile(`(?i)(?:^|[?&;\s])(?:password|pwd)=("[^"]*"|'[^']*'|[^&;\s"']+)`)
49		// credentialJSONKeyRegex operates on output of normalizeCredentialJSONKey
50		// (already lowercased, `-`/` `/`.` → `_`), so the `(?i)` flag is unnecessary.
51		credentialJSONKeyRegex  = regexp.MustCompile(`^` + dbPasswordKeyShape + `$`)
52		genericPasswordKeyRegex = regexp.MustCompile(`(?i)^(?:password|passwd|pwd)$`)
53	)
