55	// entropyThreshold is the minimum Shannon entropy for a string to be considered
56	// a secret. 4.5 was chosen through trial and error: high enough to avoid false
57	// positives on common words and identifiers, low enough to catch typical API keys
58	// and tokens which tend to have entropy well above 5.0.
59	const entropyThreshold = 4.5
60	
61	// RedactedPlaceholder is the replacement text used for redacted secrets.
62	const RedactedPlaceholder = "REDACTED"
63	
64	// placeholderSecretValues lists lowercase values that should be treated as
65	// non-secrets when they appear as a credential value: prior redactions
66	// (REDACTED / [REDACTED] / <REDACTED>), common documentation placeholders,
67	// and obviously-non-real defaults. Values matched by shape (mask runs,
68	// `<…>` brackets, `${…}` shell expansion) are handled separately.
69	var placeholderSecretValues = func() map[string]struct{} {
70		lower := strings.ToLower(RedactedPlaceholder)
71		values := []string{
72			lower, "[" + lower + "]", "<" + lower + ">",
73			"changeme", "example", "placeholder",
74			"your_password", "your_db_password", "your_secret",
75			"secret_here",
76		}
77		out := make(map[string]struct{}, len(values))
78		for _, v := range values {
79			out[v] = struct{}{}
80		}
81		return out
82	}()
83	
84	// RedactedBytes represents transcript data that has been through secret
85	// redaction. Consumers that require pre-redacted input (e.g., compact.Compact,
86	// checkpoint stores) accept this type to enforce the contract at compile time.
87	//
88	// Produced by JSONLBytes (primary constructor) or trusted wrappers for data
89	// previously persisted by checkpoint writers.
90	type RedactedBytes struct {
91		data []byte
92	}
93	
94	// Bytes returns the underlying byte slice.
95	func (r RedactedBytes) Bytes() []byte {
96		return r.data
97	}
98	
99	// Len returns the number of bytes in the redacted payload.
100	func (r RedactedBytes) Len() int {
101		return len(r.data)
102	}
103	
104	// AlreadyRedacted wraps transcript bytes known to already be redacted by a
105	// prior write path. Use this ONLY for trusted sources such as persisted
106	// checkpoint transcripts or controlled test fixtures. For fresh transcript
107	// input, use JSONLBytes.
108	func AlreadyRedacted(data []byte) RedactedBytes {
109		return RedactedBytes{data: data}
110	}
