145	type connectionStringRule struct {
146		pattern   *regexp.Regexp
147		hasSecret func(string) bool
148	}
149	
150	var connectionStringRules = []connectionStringRule{
151		{pattern: jdbcPattern, hasSecret: hasJDBCPassword},
152		{pattern: databaseURLPattern, hasSecret: hasDatabaseURLSecret},
153		{pattern: keywordDSNPattern, hasSecret: hasKeywordDSNPassword},
154		{pattern: semicolonConnPattern, hasSecret: hasSemicolonConnectionPassword},
155	}
156	
157	// String replaces secrets and PII in s using layered detection:
158	// 1. Entropy-based: high-entropy alphanumeric sequences (threshold 4.5)
159	// 2. Pattern-based: betterleaks regex rules (260+ known secret formats)
160	// 3. Credentialed URIs: URLs containing userinfo passwords
161	// 4. Database connection strings: JDBC, keyword DSNs, and semicolon strings
162	// 5. Bounded credential key/value pairs: DB_PASSWORD=...
163	// 6. PII detection: email, phone, address patterns (only when configured via ConfigurePII)
164	// A string is redacted if ANY method flags it.
165	func String(s string) string {
166		var regions []taggedRegion
167	
168		// 1. Entropy-based detection (secrets — always on).
169		for _, loc := range secretPattern.FindAllStringIndex(s, -1) {
170			start, end := loc[0], loc[1]
171	
172			// Don't consume characters that are part of JSON/string escape sequences.
173			// Example: in "controller.go\nmodel.go", the regex could match "nmodel"
174			// (consuming the 'n' from '\n'), and after replacement the '\' would be
175			// followed by 'R' from "REDACTED", creating invalid escape '\R'.
176			// Only skip for known JSON escape letters to avoid trimming real secrets
177			// that happen to follow a literal backslash in decoded content.
178			if start > 0 && s[start-1] == '\\' {
179				switch s[start] {
180				case 'n', 't', 'r', 'b', 'f', 'u', '"', '\\', '/':
181					start++
182					if end-start < 10 {
183						continue
184					}
185				}
186			}
187	
188			if shannonEntropy(s[start:end]) > entropyThreshold {
189				regions = append(regions, taggedRegion{region: region{start, end}})
190			}
191		}
192	
193		// 2. Pattern-based detection via betterleaks (secrets — always on).
194		if d := getDetector(); d != nil {
195			for _, f := range d.DetectString(s) {
196				if f.Secret == "" {
197					continue
198				}
199				searchFrom := 0
200				for {
201					idx := strings.Index(s[searchFrom:], f.Secret)
202					if idx < 0 {
203						break
204					}
205					absIdx := searchFrom + idx
206					regions = append(regions, taggedRegion{region: region{absIdx, absIdx + len(f.Secret)}})
207					searchFrom = absIdx + len(f.Secret)
208				}
209			}
210		}
211	
212		// 3. Credentialed URIs (secrets — always on).
213		for _, loc := range credentialedURIPattern.FindAllStringIndex(s, -1) {
214			regions = append(regions, taggedRegion{region: region{loc[0], loc[1]}})
215		}
216	
217		// 4. Database and connection-string detection (secrets — always on).
218		regions = append(regions, detectConnectionStrings(s)...)
219	
220		// 5. Bounded credential key/value detection (secrets — always on).
221		regions = append(regions, detectCredentialValues(s)...)
222	
223		// 6. PII detection (opt-in — only runs when configured).
224		regions = append(regions, detectPII(getPIIConfig(), s)...)
225	
226		if len(regions) == 0 {
227			return s
228		}
229	
230		// Merge overlapping regions and build result.
231		sort.Slice(regions, func(i, j int) bool {
232			if regions[i].start != regions[j].start {
233				return regions[i].start < regions[j].start
234			}
235			if regions[i].end != regions[j].end {
236				return regions[i].end > regions[j].end // larger region first
237			}
238			return regions[i].label < regions[j].label // deterministic tie-break
239		})
240		merged := []taggedRegion{regions[0]}
241		for _, r := range regions[1:] {
242			last := &merged[len(merged)-1]
243			if r.start <= last.end {
244				if r.end > last.end {
245					last.end = r.end
246				}
247				// Keep the existing label (first/larger region wins)
248			} else {
249				merged = append(merged, r)
250			}
251		}
252	
253		var b strings.Builder
254		prev := 0
255		for _, r := range merged {
256			b.WriteString(s[prev:r.start])
257			b.WriteString(replacementToken(r.label))
258			prev = r.end
259		}
260		b.WriteString(s[prev:])
261		return b.String()
262	}
263	
264	func detectConnectionStrings(s string) []taggedRegion {
265		if !strings.ContainsRune(s, '=') {
266			return nil
267		}
268		var regions []taggedRegion
269		for _, rule := range connectionStringRules {
270			regions = append(regions, detectConnectionStringRule(s, rule)...)
271		}
272		return regions
273	}
274	
275	func detectConnectionStringRule(s string, rule connectionStringRule) []taggedRegion {
276		var regions []taggedRegion
277		for _, loc := range rule.pattern.FindAllStringIndex(s, -1) {
278			start, end := loc[0], trimConnectionStringEnd(s, loc[0], loc[1])
279			if start >= end {
280				continue
281			}
282			if rule.hasSecret(s[start:end]) {
283				regions = append(regions, taggedRegion{region: region{start, end}})
284			}
285		}
286		return regions
287	}
288	
289	func trimConnectionStringEnd(s string, start, end int) int {
290		for end > start {
291			switch s[end-1] {
292			case '.', ',', ';', ':', '!', '?', ')', ']':
293				end--
294			default:
295				return end
296			}
297		}
298		return end
299	}
300	
301	func hasJDBCPassword(candidate string) bool {
302		if !strings.HasPrefix(strings.ToLower(candidate), "jdbc:") {
303			return false
304		}
305		return hasNonPlaceholderPasswordAssignment(candidate)
306	}
307	
308	func hasDatabaseURLSecret(candidate string) bool {
309		u, err := url.Parse(candidate)
310		if err != nil || u.Scheme == "" || u.Host == "" {
311			return false
312		}
313		for key, values := range u.Query() {
314			if !isPasswordQueryKey(key) {
315				continue
316			}
317			for _, value := range values {
318				if hasNonPlaceholderPasswordValue(value) {
319					return true
320				}
321			}
322		}
323		return false
324	}
325	
326	func isPasswordQueryKey(key string) bool {
327		return strings.EqualFold(key, "password") || strings.EqualFold(key, "pwd")
328	}
329	
330	func hasKeywordDSNPassword(candidate string) bool {
331		return keywordHostPattern.MatchString(candidate) &&
332			keywordUserPattern.MatchString(candidate) &&
333			hasNonPlaceholderPasswordAssignment(candidate)
334	}
335	
336	func hasSemicolonConnectionPassword(candidate string) bool {
337		return semicolonServerPattern.MatchString(candidate) &&
338			semicolonUserPattern.MatchString(candidate) &&
339			hasNonPlaceholderPasswordAssignment(candidate)
340	}
341	
342	func detectCredentialValues(s string) []taggedRegion {
343		var regions []taggedRegion
344		for _, loc := range credentialValuePattern.FindAllStringSubmatchIndex(s, -1) {
345			if len(loc) < 6 || loc[4] < 0 || loc[5] < 0 {
346				continue
347			}
348			start, end := unquoteRange(s, loc[4], loc[5])
349			if hasNonPlaceholderPasswordValue(s[start:end]) {
350				regions = append(regions, taggedRegion{region: region{start, end}})
351			}
352		}
353		return regions
354	}
355	
356	func unquoteRange(s string, start, end int) (int, int) {
357		if end-start < 2 {
358			return start, end
359		}
360		first, last := s[start], s[end-1]
361		if (first == '"' && last == '"') || (first == '\'' && last == '\'') {
362			return start + 1, end - 1
363		}
364		return start, end
365	}
366	
367	func hasNonPlaceholderPasswordAssignment(candidate string) bool {
368		for _, loc := range passwordAssignmentRegex.FindAllStringSubmatchIndex(candidate, -1) {
369			if len(loc) >= 4 && loc[2] >= 0 && loc[3] >= 0 {
370				start, end := unquoteRange(candidate, loc[2], loc[3])
371				if hasNonPlaceholderPasswordValue(candidate[start:end]) {
372					return true
373				}
374			}
375		}
376		return false
377	}
378	
379	func hasNonPlaceholderPasswordValue(value string) bool {
380		return value != "" && !isPlaceholderSecretValue(value)
381	}
382	
383	func isPlaceholderSecretValue(value string) bool {
384		trimmed := strings.Trim(strings.TrimSpace(value), `"'`)
385		if trimmed == "" {
386			return true
387		}
388		if isBracketedPlaceholder(trimmed) {
389			return true
390		}
391		normalized := strings.ToLower(trimmed)
392		if strings.HasPrefix(normalized, "${") && strings.HasSuffix(normalized, "}") {
393			return true
394		}
395		if _, ok := placeholderSecretValues[normalized]; ok {
396			return true
397		}
398		return isRepeatedCharPlaceholder(normalized)
399	}
400	
401	// bracketedPlaceholderInteriorRE matches the inside of a "<…>" placeholder
402	// shape: lowercase letters joined by `-` or `_`. Digits, mixed case, and
403	// special chars are rejected so values like `<hunter2>` or `<RealPassword>`
404	// still fall through to redaction.
405	var bracketedPlaceholderInteriorRE = regexp.MustCompile(`^[a-z][a-z_-]*$`)
406	
407	// isBracketedPlaceholder reports whether s is a "<name>" doc placeholder
408	// (e.g. "<password>", "<your-db-password>"). The minimum total length of 5
409	// keeps this from firing on `<a>` / `<ab>`.
410	func isBracketedPlaceholder(s string) bool {
411		if len(s) < 5 || s[0] != '<' || s[len(s)-1] != '>' {
412			return false
413		}
414		return bracketedPlaceholderInteriorRE.MatchString(s[1 : len(s)-1])
415	}
416	
417	// isRepeatedCharPlaceholder reports whether s is a run of a single masking
418	// character commonly used to redact values in docs and screenshots, e.g.
419	// "***", "xxxx", "....", "----". The minimum length of 3 keeps single-char
420	// or 2-char values like `x` or `**` from being treated as masks.
421	func isRepeatedCharPlaceholder(s string) bool {
422		if len(s) < 3 {
423			return false
424		}
425		first := s[0]
426		switch first {
427		case '*', 'x', '.', '-':
428		default:
429			return false
430		}
431		for i := 1; i < len(s); i++ {
432			if s[i] != first {
433				return false
434			}
435		}
436		return true
437	}
438	
439	func isCredentialJSONSecretKey(key string, credentialContext bool) bool {
440		normalized := normalizeCredentialJSONKey(key)
441		if credentialJSONKeyRegex.MatchString(normalized) {
442			return true
443		}
444		return credentialContext && genericPasswordKeyRegex.MatchString(normalized)
445	}
446	
447	func isCredentialJSONObject(obj map[string]any) bool {
448		var hasHost, hasUser bool
449		for key := range obj {
450			switch normalizeCredentialJSONKey(key) {
451			case "host", "hostname", "server", "addr", "address", "datasource", "data_source":
452				hasHost = true
453			case "user", "username", "userid", "user_id", "uid":
454				hasUser = true
455			}
456			if hasHost && hasUser {
457				return true
458			}
459		}
460		return false
461	}
462	
463	func normalizeCredentialJSONKey(key string) string {
464		key = strings.ToLower(strings.TrimSpace(key))
465		key = strings.ReplaceAll(key, "-", "_")
466		key = strings.ReplaceAll(key, " ", "_")
467		// Flattened-config exporters (Spring, dotnet, Hashicorp Vault) emit dotted keys
468		// like "db.password" or "mysql.root.password"; treat them like underscored.
469		key = strings.ReplaceAll(key, ".", "_")
470		return key
471	}
472	
473	// Bytes is a convenience wrapper around String for []byte content.
474	func Bytes(b []byte) []byte {
475		s := string(b)
476		redacted := String(s)
477		if redacted == s {
478			return b
479		}
480		return []byte(redacted)
481	}
482	
483	// JSONLBytes redacts secrets in JSONL-formatted byte content and returns
484	// the result as RedactedBytes, certifying the output has been through redaction.
485	func JSONLBytes(b []byte) (RedactedBytes, error) {
486		s := string(b)
487		redacted, err := JSONLContent(s)
488		if err != nil {
489			return RedactedBytes{}, err
490		}
491		if redacted == s {
492			return RedactedBytes{data: b}, nil
493		}
494		return RedactedBytes{data: []byte(redacted)}, nil
495	}
496	
497	// JSONLContent parses each line as JSON to determine which string values
498	// need redaction, then performs targeted replacements on the raw JSON bytes.
499	// Lines with no secrets are returned unchanged, preserving original formatting.
500	//
501	// For multi-line JSON content (e.g., pretty-printed single JSON objects like
502	// OpenCode export), the function first attempts to parse the entire content as
503	// a single JSON value. This ensures field-aware redaction (which skips ID fields)
504	// is used instead of falling back to entropy-based detection on raw text lines,
505	// which would corrupt high-entropy identifiers.
506	func JSONLContent(content string) (string, error) {
507		// Try parsing the entire content as a single JSON value first.
508		// Uses a streaming decoder to avoid copying the full content into []byte.
509		// After decoding, attempts a second Decode to confirm EOF — if it succeeds,
510		// the content is JSONL (multiple values) and we fall through to line-by-line.
511		trimmed := strings.TrimSpace(content)
512		if len(trimmed) > 0 {
513			dec := json.NewDecoder(strings.NewReader(trimmed))
514			var parsed any
515			if err := dec.Decode(&parsed); err == nil && isSingleJSONValue(dec) {
516				// Content is a single JSON value (object/array) — redact field-aware.
517				result, err := applyJSONReplacements(content, collectJSONLReplacements(parsed))
518				if err != nil {
519					return "", err
520				}
521				return result, nil
522			}
523		}
524	
525		// Fall back to line-by-line JSONL processing.
526		lines := strings.Split(content, "\n")
527		var b strings.Builder
528		for i, line := range lines {
529			if i > 0 {
530				b.WriteByte('\n')
531			}
532			lineTrimmed := strings.TrimSpace(line)
533			if lineTrimmed == "" {
534				b.WriteString(line)
535				continue
536			}
537			var parsed any
538			if err := json.Unmarshal([]byte(lineTrimmed), &parsed); err != nil {
539				b.WriteString(String(line))
540				continue
541			}
542			result, err := applyJSONReplacements(line, collectJSONLReplacements(parsed))
543			if err != nil {
544				return "", err
545			}
546			b.WriteString(result)
547		}
548		return b.String(), nil
549	}
550	
551	// applyJSONReplacements applies collected (original, redacted) string pairs
552	// to the raw JSON text, replacing JSON-encoded originals with their redacted forms.
553	// Returns s unchanged if repls is empty.
554	func applyJSONReplacements(s string, repls []jsonReplacement) (string, error) {
555		if len(repls) == 0 {
556			return s, nil
557		}
558		for _, r := range repls {
559			origJSON, err := jsonEncodeString(r.original)
560			if err != nil {
561				return "", err
562			}
563			replJSON, err := jsonEncodeString(r.redacted)
564			if err != nil {
565				return "", err
566			}
567			if r.key == "" {
568				s = strings.ReplaceAll(s, origJSON, replJSON)
569				continue
570			}
571			keyJSON, err := jsonEncodeString(r.key)
572			if err != nil {
573				return "", err
574			}
575			s = replaceKeyedJSONValue(s, keyJSON, origJSON, replJSON)
576		}
577		return s, nil
578	}
579	
580	// replaceKeyedJSONValue replaces every occurrence of origJSON that follows
581	// keyJSON + optional whitespace + ':' + optional whitespace. Restricts
582	// substitution to value positions so a key's own redacted text is not
583	// rewritten when it collides with another field's value.
584	func replaceKeyedJSONValue(s, keyJSON, origJSON, replJSON string) string {
585		if !strings.Contains(s, keyJSON) {
586			return s
587		}
588		var b strings.Builder
589		b.Grow(len(s))
590		i := 0
591		for i < len(s) {
592			j := strings.Index(s[i:], keyJSON)
593			if j < 0 {
594				b.WriteString(s[i:])
595				break
596			}
597			keyEnd := i + j + len(keyJSON)
598			b.WriteString(s[i : i+j])
599			b.WriteString(keyJSON)
600			p := keyEnd
601			for p < len(s) && isJSONWhitespace(s[p]) {
602				p++
603			}
604			if p >= len(s) || s[p] != ':' {
605				i = keyEnd
606				continue
607			}
608			p++
609			for p < len(s) && isJSONWhitespace(s[p]) {
610				p++
611			}
612			if p+len(origJSON) <= len(s) && s[p:p+len(origJSON)] == origJSON {
613				b.WriteString(s[keyEnd:p])
614				b.WriteString(replJSON)
615				i = p + len(origJSON)
616				continue
617			}
618			i = keyEnd
619		}
620		return b.String()
621	}
