637	// collectJSONLReplacements walks a parsed JSON value and collects unique string
638	// replacements for values that need redaction.
639	func collectJSONLReplacements(v any) []jsonReplacement {
640		seen := make(map[string]bool)
641		var repls []jsonReplacement
642		var walk func(key string, credentialContext bool, v any)
643		walk = func(key string, credentialContext bool, v any) {
644			switch val := v.(type) {
645			case map[string]any:
646				if shouldSkipJSONLObject(val) {
647					return
648				}
649				childCredentialContext := credentialContext || isCredentialJSONObject(val)
650				for k, child := range val {
651					if shouldSkipJSONLField(k) {
652						continue
653					}
654					walk(k, childCredentialContext, child)
655				}
656			case []any:
657				for _, child := range val {
658					walk("", credentialContext, child)
659				}
660			case string:
661				redacted := String(val)
662				if redacted == val && isCredentialJSONSecretKey(key, credentialContext) && hasNonPlaceholderPasswordValue(val) {
663					redacted = RedactedPlaceholder
664				}
665				if redacted != val {
666					seenKey := key + "\x00" + val
667					if !seen[seenKey] {
668						seen[seenKey] = true
669						repls = append(repls, jsonReplacement{key: key, original: val, redacted: redacted})
670					}
671				}
672			}
673		}
674		walk("", false, v)
675		return repls
676	}
