678	// shouldSkipJSONLField returns true if a JSON key should be excluded from scanning/redaction.
679	// Skips "signature" (exact), ID fields (ending in "id"/"ids"), and common path/directory fields.
680	func shouldSkipJSONLField(key string) bool {
681		if key == "signature" {
682			return true
683		}
684		lower := strings.ToLower(key)
685	
686		// Skip ID fields
687		if strings.HasSuffix(lower, "id") || strings.HasSuffix(lower, "ids") {
688			return true
689		}
690	
691		// Skip common path and directory fields from agent transcripts.
692		// These appear frequently in tool calls and are structural, not secrets.
693		switch lower {
694		case "filepath", "file_path", "cwd", "root", "directory", "dir", "path":
695			return true
696		}
697	
698		return false
699	}
