707	func shannonEntropy(s string) float64 {
708		if len(s) == 0 {
709			return 0
710		}
711		freq := make(map[byte]int)
712		for i := range len(s) {
713			freq[s[i]]++
714		}
715		length := float64(len(s))
716		var entropy float64
717		for _, count := range freq {
718			p := float64(count) / length
719			entropy -= p * math.Log2(p)
720		}
721		return entropy
722	}
