724	// jsonEncodeString returns the JSON encoding of s without HTML escaping.
725	func jsonEncodeString(s string) (string, error) {
726		var buf bytes.Buffer
727		enc := json.NewEncoder(&buf)
728		enc.SetEscapeHTML(false)
729		if err := enc.Encode(s); err != nil {
730			return "", fmt.Errorf("json encode string: %w", err)
731		}
732		return strings.TrimSuffix(buf.String(), "\n"), nil
733	}
