80	//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"assistant","ts":"...","id":"msg_xxx","content":[{"type":"text","text":"..."},{"type":"tool_use","id":"...","name":"...","input":{...},"result":{"output":"...","status":"..."}}]}
81	func Compact(redacted redact.RedactedBytes, opts MetadataFields) ([]byte, error) {
82		content := redacted.Bytes()
83	
84		// Formats that need detection on raw content before line truncation:
85		// - Single-object formats (OpenCode, Gemini): SliceFromLine would cut
86		//   a JSON object mid-value. They handle StartLine as a message-index offset.
87		// - Codex: session_meta header is only on the first line. Codex handles
88		//   StartLine as a response_item index offset.
89		if isOpenCodeFormat(content) {
90			return compactOpenCode(content, opts)
91		}
92	
93		if isGeminiFormat(content) {
94			return compactGemini(content, opts)
95		}
96	
97		if isCodexFormat(content) {
98			return compactCodex(content, opts)
99		}
100	
101		truncated := transcript.SliceFromLine(content, opts.StartLine)
102		if truncated == nil {
103			truncated = []byte{}
104		}
105	
106		if isCopilotFormat(truncated) {
107			return compactCopilot(truncated, opts)
108		}
109	
110		if isDroidFormat(truncated) {
111			return compactDroid(truncated, opts)
112		}
113	
114		return compactJSONL(truncated, opts)
115	}
