// Package agent prototypes a content-targeted redaction approach for AI agent
// transcripts. Instead of scanning every JSON string and using an allowlist of
// keys to skip (ids, paths, signatures, …), it inverts the model: each agent
// has a Walker that knows its transcript schema and emits only the strings that
// actually carry user/assistant/tool content. Structural fields are unreachable
// by construction.
//
// Status: prototype. Single agent (Claude Code) wired up to validate the
// abstraction before extracting more agents.
package agent

// Kind tags a string emitted by a Walker with what kind of content it is.
// The redactor uses this to decide how aggressively to scan: tool I/O can be
// scanned at a lower entropy threshold than chat text because tool calls are
// the most likely place for secrets to appear verbatim.
type Kind int

const (
	// KindUserText is text the user wrote (chat input).
	KindUserText Kind = iota
	// KindAssistantText is text the assistant emitted (chat output, thinking).
	KindAssistantText
	// KindToolName is the name of a tool being invoked. Public surface; not scanned.
	KindToolName
	// KindToolInput is a string anywhere inside a tool's input object (recursively).
	KindToolInput
	// KindToolOutput is the textual output returned by a tool.
	KindToolOutput
)

// Visitor receives each content-bearing string from a Walker.
type Visitor interface {
	OnString(kind Kind, value string)
}

// VisitorFunc adapts a plain function to the Visitor interface.
type VisitorFunc func(kind Kind, value string)

// OnString implements Visitor.
func (f VisitorFunc) OnString(kind Kind, value string) { f(kind, value) }

// Walker parses an agent's native transcript format and emits content strings
// to the visitor. Walkers MUST NOT emit structural fields (ids, paths,
// timestamps, signatures, model names, token counts).
type Walker func(raw []byte, v Visitor) error

package agent

import (
	"bufio"
	"bytes"
	"encoding/json"
	"fmt"
	"io"
)

// WalkClaudeCode parses a Claude Code session JSONL transcript and emits each
// content-bearing string to v. Structural fields (uuid, promptId, sessionId,
// requestId, timestamps, cwd, gitBranch, version, message.id, message.model,
// signatures, token counts, tool_use.id, tool_result.tool_use_id, …) are
// never emitted.
//
// Schema reference (one line per JSON object):
//
//	{"type":"user","message":{"role":"user","content": "..." | [block,...]}, ...metadata...}
//	{"type":"assistant","message":{"id":"msg_…","content":[block,...]}, ...metadata...}
//
// User content blocks:
//
//	{"type":"text","text":"..."}                            → KindUserText
//	{"type":"tool_result","tool_use_id":"…","content":"…"}  → KindToolOutput
//	{"type":"image", ...}                                   → skipped
//
// Assistant content blocks:
//
//	{"type":"text","text":"..."}                          → KindAssistantText
//	{"type":"thinking","thinking":"…","signature":"…"}    → text only; signature skipped
//	{"type":"redacted_thinking", ...}                     → skipped (already redacted)
//	{"type":"tool_use","name":"…","input":{…}}            → name + recursive input
func WalkClaudeCode(raw []byte, v Visitor) error {
	r := bufio.NewReader(bytes.NewReader(raw))
	for {
		line, err := r.ReadBytes('\n')
		if len(bytes.TrimSpace(line)) > 0 {
			if walkErr := walkClaudeCodeLine(line, v); walkErr != nil {
				return walkErr
			}
		}
		if err == io.EOF {
			return nil
		}
		if err != nil {
			return fmt.Errorf("read jsonl: %w", err)
		}
	}
}

func walkClaudeCodeLine(line []byte, v Visitor) error {
	var head struct {
		Type    string          `json:"type"`
		Message json.RawMessage `json:"message"`
	}
	if err := json.Unmarshal(line, &head); err != nil {
		// Malformed line — skip silently. Matches existing redactor behavior.
		return nil
	}
	switch head.Type {
	case "user", "human":
		return walkClaudeUserMessage(head.Message, v)
	case "assistant":
		return walkClaudeAssistantMessage(head.Message, v)
	}
	// Other types (progress, file-history-snapshot, summary, system, …) carry
	// no user-authored content.
	return nil
}

func walkClaudeUserMessage(msg json.RawMessage, v Visitor) error {
	if len(msg) == 0 {
		return nil
	}
	var envelope struct {
		Content json.RawMessage `json:"content"`
	}
	if err := json.Unmarshal(msg, &envelope); err != nil {
		return nil
	}
	if len(envelope.Content) == 0 {
		return nil
	}
	// Content can be a plain string OR an array of typed blocks.
	var asString string
	if json.Unmarshal(envelope.Content, &asString) == nil {
		v.OnString(KindUserText, asString)
		return nil
	}
	var blocks []map[string]json.RawMessage
	if err := json.Unmarshal(envelope.Content, &blocks); err != nil {
		return nil
	}
	for _, b := range blocks {
		switch unquote(b["type"]) {
		case "text":
			v.OnString(KindUserText, unquote(b["text"]))
		case "tool_result":
			// content can be a string or an array of {type:"text",text:"…"}/{type:"image",…}
			emitToolResultContent(b["content"], v)
		}
		// image blocks: deliberately skipped.
	}
	return nil
}

func walkClaudeAssistantMessage(msg json.RawMessage, v Visitor) error {
	if len(msg) == 0 {
		return nil
	}
	var envelope struct {
		Content json.RawMessage `json:"content"`
	}
	if err := json.Unmarshal(msg, &envelope); err != nil {
		return nil
	}
	var blocks []map[string]json.RawMessage
	if err := json.Unmarshal(envelope.Content, &blocks); err != nil {
		return nil
	}
	for _, b := range blocks {
		switch unquote(b["type"]) {
		case "text":
			v.OnString(KindAssistantText, unquote(b["text"]))
		case "thinking":
			// Emit the thinking text; signature is intentionally not emitted —
			// it's a high-entropy structural field that the current redactor
			// false-positives on at threshold 4.5.
			v.OnString(KindAssistantText, unquote(b["thinking"]))
		case "redacted_thinking":
			// Already redacted by the provider.
		case "tool_use":
			v.OnString(KindToolName, unquote(b["name"]))
			emitJSONStrings(b["input"], KindToolInput, v)
		}
	}
	return nil
}

// emitToolResultContent handles tool_result.content, which is either a string
// or an array of typed blocks similar to user content.
func emitToolResultContent(raw json.RawMessage, v Visitor) {
	if len(raw) == 0 {
		return
	}
	var asString string
	if json.Unmarshal(raw, &asString) == nil {
		v.OnString(KindToolOutput, asString)
		return
	}
	var blocks []map[string]json.RawMessage
	if json.Unmarshal(raw, &blocks) != nil {
		return
	}
	for _, b := range blocks {
		if unquote(b["type"]) == "text" {
			v.OnString(KindToolOutput, unquote(b["text"]))
		}
	}
}

// emitJSONStrings recursively walks any JSON value and emits every string leaf
// under the given kind. Used for tool_use.input, which is arbitrary
// tool-defined JSON — we can't enumerate schemas so we scan all strings.
func emitJSONStrings(raw json.RawMessage, kind Kind, v Visitor) {
	if len(raw) == 0 {
		return
	}
	var any interface{}
	if json.Unmarshal(raw, &any) != nil {
		return
	}
	walkAny(any, kind, v)
}

func walkAny(node any, kind Kind, v Visitor) {
	switch t := node.(type) {
	case string:
		v.OnString(kind, t)
	case []any:
		for _, child := range t {
			walkAny(child, kind, v)
		}
	case map[string]any:
		for _, child := range t {
			walkAny(child, kind, v)
		}
	}
}

func unquote(raw json.RawMessage) string {
	var s string
	if json.Unmarshal(raw, &s) == nil {
		return s
	}
	return ""
}

package agent

import (
	"bytes"
	"encoding/json"
	"fmt"

	"github.com/entireio/cli/redact"
)

// ScanFunc redacts a single content string. Defaults to redact.String. Tests
// (or future callers that want a lower entropy threshold for content-only
// scanning) can pass a custom scanner.
type ScanFunc func(s string) string

// Redact walks raw with walk, runs scan on every content string, and rewrites
// the raw bytes in place by replacing each changed JSON-encoded string with
// its redacted form. Structural fields are never visited so they cannot be
// false-positively matched.
//
// Returns the rewritten bytes and the count of distinct replacements applied.
// The output is byte-identical to the input when nothing required redaction.
func Redact(walk Walker, raw []byte, scan ScanFunc) ([]byte, int, error) {
	if scan == nil {
		scan = redact.String
	}
	seen := make(map[string]string)
	visitor := VisitorFunc(func(_ Kind, value string) {
		if value == "" {
			return
		}
		if _, done := seen[value]; done {
			return
		}
		redacted := scan(value)
		if redacted != value {
			seen[value] = redacted
		} else {
			// Memoize negative result so we don't re-scan.
			seen[value] = value
		}
	})
	if err := walk(raw, visitor); err != nil {
		return nil, 0, err
	}

	out := raw
	count := 0
	for original, redacted := range seen {
		if original == redacted {
			continue
		}
		origJSON, err := encodeJSONString(original)
		if err != nil {
			return nil, 0, err
		}
		replJSON, err := encodeJSONString(redacted)
		if err != nil {
			return nil, 0, err
		}
		if !bytes.Contains(out, origJSON) {
			continue
		}
		out = bytes.ReplaceAll(out, origJSON, replJSON)
		count++
	}
	return out, count, nil
}

func encodeJSONString(s string) ([]byte, error) {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	if err := enc.Encode(s); err != nil {
		return nil, fmt.Errorf("encode json string: %w", err)
	}
	return bytes.TrimSuffix(buf.Bytes(), []byte("\n")), nil
}

package agent

