// collect is a Visitor that records every (kind, value) it sees, for assertion.
type collect struct{ events []event }
type event struct {
	kind  Kind
	value string
}

func (c *collect) OnString(k Kind, v string) { c.events = append(c.events, event{k, v}) }

func (c *collect) sortedValues() []string {
	out := make([]string, len(c.events))
	for i, e := range c.events {
		out[i] = e.value
	}
	sort.Strings(out)
	return out
}

func (c *collect) has(kind Kind, value string) bool {
	for _, e := range c.events {
		if e.kind == kind && e.value == value {
			return true
		}
	}
	return false
}

