func TestWalkClaudeCode_EmitsContentOnly(t *testing.T) {
	t.Parallel()
	lines := strings.Join([]string{
		claudeUserLine,
		claudeAssistantThinkingLine,
		claudeAssistantToolUseLine,
		claudeToolResultLine,
	}, "\n")

	var c collect
	if err := WalkClaudeCode([]byte(lines), &c); err != nil {
		t.Fatalf("walk: %v", err)
	}

	// Content that MUST be visited.
	wantContent := []struct {
		kind  Kind
		value string
	}{
		{KindUserText, "please run AWS_SECRET_ACCESS_KEY=wJalrXUtnFEMI/K7MDENG/bPxRfiCYEXAMPLEKEY against staging"},
		{KindAssistantText, "User wants me to run a shell command. I should be careful with credentials."},
		{KindAssistantText, "I'll check the staging environment."},
		{KindToolName, "Bash"},
		{KindToolInput, "curl -H 'Authorization: Bearer REDACTED' https://api.example.com"},
		{KindToolInput, "call staging api"},
		{KindToolOutput, "$ env\nDATABASE_URL=REDACTED"},
	}
	for _, w := range wantContent {
		if !c.has(w.kind, w.value) {
			t.Errorf("walker did not emit kind=%v value=%q", w.kind, w.value)
		}
	}

	// Structural values that MUST NOT be visited. These are the values that
	// the current allowlist-based redactor either skips by key name or
	// false-positives on by entropy. With the content-positive walker they
	// are unreachable.
	structural := []string{
		"206230ce-3c3a-4668-8b27-b29120637230", // parentUuid
		"1a789a48-ac83-46b6-a746-90ff5bb455ad", // promptId
		"55d2b925-6228-4ab1-9a5f-9c31fb9f4a29", // uuid
		"8b89dece-0f9b-4965-8436-fcec80f5ea06", // sessionId
		"f3986f8d-4f08-4afd-91e2-54a88a77827d", // assistant uuid
		"REDACTED",         // requestId
		"req_222",
		"msg_01A8w8vJNhp54SKt6N4Pdg6W",
		"msg_02bbbbb",
		"toolu_01XYZ", // tool_use_id (metadata, not content)
		"REDACTED", // signature
		"claude-opus-4-6",
		"2026-03-18T00:03:14.992Z",
		"/Users/private/entire/test-repos/test-repo",
		"test-gemini",
		"prompt-uuid-here-do-not-redact",
	}
	for _, s := range structural {
		for _, e := range c.events {
			if e.value == s {
				t.Errorf("walker emitted structural value as kind=%v: %q (must not be visited)", e.kind, s)
			}
		}
	}
}

func TestRedact_ScansOnlyContent(t *testing.T) {
	t.Parallel()
	lines := strings.Join([]string{
		claudeUserLine,
		claudeAssistantToolUseLine,
		claudeToolResultLine,
	}, "\n")

	out, n, err := Redact(WalkClaudeCode, []byte(lines), redact.String)
	if err != nil {
		t.Fatalf("redact: %v", err)
	}
	if n == 0 {
		t.Fatalf("expected at least one redaction, got 0\nout: %s", out)
	}

	// All three planted secrets must be gone from the output.
	plantedSecrets := []string{
		"wJalrXUtnFEMI/K7MDENG/bPxRfiCYEXAMPLEKEY",
		"REDACTED",
		"hunter2-real-password",
	}
	for _, secret := range plantedSecrets {
		if bytes.Contains(out, []byte(secret)) {
			t.Errorf("secret %q survived redaction", secret)
		}
	}

	// Structural UUIDs and the assistant signature must be untouched —
	// proving the content-positive walker cannot false-positive on them.
	mustSurvive := []string{
		"1a789a48-ac83-46b6-a746-90ff5bb455ad", // promptId
		"55d2b925-6228-4ab1-9a5f-9c31fb9f4a29", // user uuid (also a sessionId substring elsewhere)
		"toolu_01XYZ",
		"msg_02bbbbb",
		"req_222",
	}
	for _, s := range mustSurvive {
		if !bytes.Contains(out, []byte(s)) {
			t.Errorf("structural value %q was incorrectly redacted", s)
		}
	}
}

// Demonstrates the headline win: a low-entropy planted secret that the
// current global redactor with threshold 4.5 misses, but a content-only pass
// with a lower threshold catches — without any risk to structural fields,
// because they are never visited.
func TestRedact_LowThresholdCatchesLowEntropySecret(t *testing.T) {
	t.Parallel()
	// "password123password123" has entropy ~3.4 — well below the global 4.5
	// threshold, so the current generic redactor leaves it alone. But it's
	// obviously a secret if it shows up in a tool's `password=` argument.
	const lowEntropySecret = "password123password123"
	line := `{"type":"assistant","message":{"id":"msg_x","role":"assistant","content":[{"type":"tool_use","id":"toolu_x","name":"Bash","input":{"command":"mysql -u root -p` + lowEntropySecret + `"}}]},"uuid":"u","timestamp":"t"}`

	// Custom scanner with lowered entropy threshold via a simple shim: any
	// value containing "password" verbatim is redacted. In a real wiring
	// we'd thread an entropy threshold into redact.String; this prototype
	// just demonstrates that the redactor accepts a custom ScanFunc and
	// that lowering the bar is safe — because the only things the scanner
	// ever sees are content strings.
	lowerThreshold := func(s string) string {
		// Keep the existing detectors AND add the cheap heuristic.
		base := redact.String(s)
		if base != s {
			return base
		}
		if strings.Contains(strings.ToLower(s), "password") {
			return "REDACTED"
		}
		return s
	}

	out, _, err := Redact(WalkClaudeCode, []byte(line), lowerThreshold)
	if err != nil {
		t.Fatalf("redact: %v", err)
	}
	if bytes.Contains(out, []byte(lowEntropySecret)) {
		t.Errorf("low-entropy secret survived: %s", out)
	}
	// And the structural UUID is still there.
	if !bytes.Contains(out, []byte("toolu_x")) {
		t.Error("tool_use id was incorrectly redacted")
	}
}

