// Package transcript provides content-targeted redaction for AI agent
// transcripts. Each agent has a Walker that knows its transcript schema and
// emits only the strings carrying user/assistant/tool content; structural
// fields (ids, paths, signatures, …) are unreachable, so the scanner can't
// false-positive on them.
package transcript

// Kind tags a string emitted by a Walker so a redactor can vary policy by
// content type (e.g. scan tool I/O more aggressively than chat text).
type Kind int

const (
	KindUserText Kind = iota
	KindAssistantText
	KindToolInput
	KindToolOutput
)

// Visitor receives each content-bearing string from a Walker.
type Visitor interface {
	OnString(kind Kind, value string)
}

// VisitorFunc adapts a plain function to the Visitor interface.
type VisitorFunc func(kind Kind, value string)

func (f VisitorFunc) OnString(kind Kind, value string) { f(kind, value) }

// Walker parses an agent's native transcript and emits content strings to v.
// Walkers MUST NOT emit structural fields.
type Walker func(raw []byte, v Visitor) error

package transcript

import (
	"bytes"
	"encoding/json"
	"fmt"
	"strings"

	"github.com/entireio/cli/redact"
)

// ScanFunc redacts a single content string. Defaults to redact.String.
// Custom scanners can use a lower entropy threshold than the global scanner
// because they only ever see content strings — structural fields can't reach
// them.
type ScanFunc func(s string) string

// Redact walks raw with walk, runs scan on every distinct content string, and
// rewrites the raw bytes by replacing each changed JSON-encoded value with
// its redacted form in a single pass. Returns the rewritten bytes and the
// number of distinct replacements applied.
func Redact(walk Walker, raw []byte, scan ScanFunc) ([]byte, int, error) {
	if scan == nil {
		scan = redact.String
	}
	seen := make(map[string]string)
	v := VisitorFunc(func(_ Kind, value string) {
		if value == "" {
			return
		}
		if _, done := seen[value]; done {
			return
		}
		seen[value] = scan(value)
	})
	if err := walk(raw, v); err != nil {
		return nil, 0, err
	}

	pairs := make([]string, 0, len(seen)*2)
	for original, redacted := range seen {
		if original == redacted {
			continue
		}
		origJSON, err := encodeJSONString(original)
		if err != nil {
			return nil, 0, err
		}
		replJSON, err := encodeJSONString(redacted)
		if err != nil {
			return nil, 0, err
		}
		pairs = append(pairs, origJSON, replJSON)
	}
	if len(pairs) == 0 {
		return raw, 0, nil
	}
	return []byte(strings.NewReplacer(pairs...).Replace(string(raw))), len(pairs) / 2, nil
}

func encodeJSONString(s string) (string, error) {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	if err := enc.Encode(s); err != nil {
		return "", fmt.Errorf("encode json string: %w", err)
	}
	return strings.TrimSuffix(buf.String(), "\n"), nil
}

