package transcript

import (
	"bufio"
	"bytes"
	"encoding/json"
	"fmt"
)

const (
	// Top-level line types in Claude Code's session JSONL.
	claudeTypeUser      = "user"
	claudeTypeHuman     = "human" // legacy alias for user
	claudeTypeAssistant = "assistant"

	// Content block types appearing inside message.content arrays.
	claudeBlockText             = "text"
	claudeBlockToolUse          = "tool_use"
	claudeBlockToolResult       = "tool_result"
	claudeBlockThinking         = "thinking"
	claudeBlockRedactedThinking = "redacted_thinking"

	// Matches the 10MB buffer the existing compactor uses (compact/codex.go).
	maxJSONLLineBytes = 10 * 1024 * 1024
)

// WalkClaudeCode parses a Claude Code session JSONL transcript and emits each
// content-bearing string to v. Structural fields (uuid, promptId, sessionId,
// requestId, signatures, model, timestamps, cwd, gitBranch, tool ids, …) are
// never emitted.
//
// Schema reference (one JSON object per line):
//
//	{"type":"user","message":{"role":"user","content": "..." | [block,...]}, ...}
//	{"type":"assistant","message":{"id":"msg_…","content":[block,...]}, ...}
//
// User content blocks: text → KindUserText, tool_result → KindToolOutput,
// image → skipped. Assistant content blocks: text/thinking → KindAssistantText,
// tool_use → recursive scan of input as KindToolInput, redacted_thinking → skipped.
func WalkClaudeCode(raw []byte, v Visitor) error {
	sc := bufio.NewScanner(bytes.NewReader(raw))
	sc.Buffer(make([]byte, 0, 64*1024), maxJSONLLineBytes)
	for sc.Scan() {
		line := sc.Bytes()
		if len(bytes.TrimSpace(line)) == 0 {
			continue
		}
		walkClaudeCodeLine(line, v)
	}
	if err := sc.Err(); err != nil {
		return fmt.Errorf("scan jsonl: %w", err)
	}
	return nil
}

func walkClaudeCodeLine(line []byte, v Visitor) {
	var head struct {
		Type    string          `json:"type"`
		Message json.RawMessage `json:"message"`
	}
	if json.Unmarshal(line, &head) != nil {
		return
	}
	switch head.Type {
	case claudeTypeUser, claudeTypeHuman:
		walkClaudeBlocks(head.Message, v, dispatchUserBlock)
	case claudeTypeAssistant:
		walkClaudeBlocks(head.Message, v, dispatchAssistantBlock)
	}
}

// walkClaudeBlocks parses message.content (a string OR an array of typed
// blocks) and dispatches each block to the per-role handler. When content is
// a bare string it counts as a single text block.
func walkClaudeBlocks(msg json.RawMessage, v Visitor, dispatch func(block map[string]json.RawMessage, v Visitor)) {
	if len(msg) == 0 {
		return
	}
	var envelope struct {
		Content json.RawMessage `json:"content"`
	}
	if json.Unmarshal(msg, &envelope) != nil || len(envelope.Content) == 0 {
		return
	}
	var asString string
	if json.Unmarshal(envelope.Content, &asString) == nil {
		dispatch(map[string]json.RawMessage{
			"type": json.RawMessage(`"` + claudeBlockText + `"`),
			"text": envelope.Content,
		}, v)
		return
	}
	var blocks []map[string]json.RawMessage
	if json.Unmarshal(envelope.Content, &blocks) != nil {
		return
	}
	for _, b := range blocks {
		dispatch(b, v)
	}
}

func dispatchUserBlock(b map[string]json.RawMessage, v Visitor) {
	switch unquote(b["type"]) {
	case claudeBlockText:
		v.OnString(KindUserText, unquote(b["text"]))
	case claudeBlockToolResult:
		emitToolResultContent(b["content"], v)
	}
}

func dispatchAssistantBlock(b map[string]json.RawMessage, v Visitor) {
	switch unquote(b["type"]) {
	case claudeBlockText:
		v.OnString(KindAssistantText, unquote(b["text"]))
	case claudeBlockThinking:
		// Emits thinking text only. The neighboring `signature` field is a
		// high-entropy structural value that the current generic redactor
		// false-positives on — keeping it unvisited is the structural fix.
		v.OnString(KindAssistantText, unquote(b["thinking"]))
	case claudeBlockToolUse:
		emitJSONStrings(b["input"], KindToolInput, v)
	case claudeBlockRedactedThinking:
		// Already redacted by the provider.
	}
}

func emitToolResultContent(raw json.RawMessage, v Visitor) {
	if len(raw) == 0 {
		return
	}
	var asString string
	if json.Unmarshal(raw, &asString) == nil {
		v.OnString(KindToolOutput, asString)
		return
	}
	var blocks []map[string]json.RawMessage
	if json.Unmarshal(raw, &blocks) != nil {
		return
	}
	for _, b := range blocks {
		if unquote(b["type"]) == claudeBlockText {
			v.OnString(KindToolOutput, unquote(b["text"]))
		}
	}
}

// emitJSONStrings recursively walks any JSON value and emits every string
// leaf under kind. Used for tool_use.input, which is arbitrary tool-defined
// JSON — we can't enumerate schemas so we scan all strings.
func emitJSONStrings(raw json.RawMessage, kind Kind, v Visitor) {
	if len(raw) == 0 {
		return
	}
	var node interface{}
	if json.Unmarshal(raw, &node) != nil {
		return
	}
	walkAny(node, kind, v)
}

func walkAny(node any, kind Kind, v Visitor) {
	switch t := node.(type) {
	case string:
		v.OnString(kind, t)
	case []any:
		for _, child := range t {
			walkAny(child, kind, v)
		}
	case map[string]any:
		for _, child := range t {
			walkAny(child, kind, v)
		}
	}
}

func unquote(raw json.RawMessage) string {
	var s string
	if json.Unmarshal(raw, &s) == nil {
		return s
	}
	return ""
}

