205				return nil, fmt.Errorf("reading codex line: %w", err)
206			}
207	
208			if len(bytes.TrimSpace(lineBytes)) > 0 {
209				var cl codexLine
210				if json.Unmarshal(lineBytes, &cl) == nil {
211					if cl.Type == "response_item" || isCodexTokenCountLine(cl) {
212						lines = append(lines, cl)
213					}
214				}
215			}
216	
217			if err == io.EOF {
218				break
219			}
220		}
221		return lines, nil
222	}
223	
224	// isCodexTokenCountLine checks if a codexLine is an event_msg with token_count payload.
225	func isCodexTokenCountLine(cl codexLine) bool {
226		if cl.Type != "event_msg" {
227			return false
228		}
229		var p struct {
230			Type string `json:"type"`
231		}
232		return json.Unmarshal(cl.Payload, &p) == nil && p.Type == "token_count"
233	}
234	
235	// codexTokenCount extracts input/output tokens from a token_count payload.
236	func codexTokenCount(payload json.RawMessage) (input, output int) {
237		var tc struct {
238			InputTokens  int `json:"input_tokens"`
239			OutputTokens int `json:"output_tokens"`
240		}
241		if json.Unmarshal(payload, &tc) == nil {
242			return tc.InputTokens, tc.OutputTokens
243		}
244		return 0, 0
245	}
246	
247	// codexUserText extracts the actual user prompt text from a Codex user message,
248	// dropping system-injected content (AGENTS.md, environment_context, permissions,
249	// turn_aborted, etc.).
250	func codexUserText(raw json.RawMessage) string {
251		var blocks []struct {
252			Type string `json:"type"`
253			Text string `json:"text"`
254		}
255		if json.Unmarshal(raw, &blocks) != nil {
256			return ""
257		}
258	
259		var texts []string
260		for _, b := range blocks {
261			if b.Type != "input_text" {
262				continue
263			}
264			// Skip system-injected content.
265			if isCodexSystemContent(b.Text) {
266				continue
267			}
268			stripped := textutil.StripIDEContextTags(b.Text)
269			if stripped != "" {
270				texts = append(texts, stripped)
271			}
272		}
273	
274		return strings.Join(texts, "\n\n")
275	}
276	
277	// isCodexSystemContent returns true for content blocks that are system-injected
278	// rather than user-authored.
279	func isCodexSystemContent(text string) bool {

280		prefixes := []string{
281			"<permissions",
282			"<collaboration_mode>",
283			"<skills_instructions>",
284			"<environment_context>",
285			"<turn_aborted>",
286			"# AGENTS.md",
287		}
288		for _, p := range prefixes {
289			if len(text) >= len(p) && text[:len(p)] == p {
290				return true
291			}
292		}
293		return false
294	}
295	
296	// codexAssistantText extracts text from a Codex assistant message content array.
297	func codexAssistantText(raw json.RawMessage) string {
298		var blocks []struct {
299			Type string `json:"type"`
300			Text string `json:"text"`
301		}
302		if json.Unmarshal(raw, &blocks) != nil {
303			return ""
304		}
305		var texts []string
306		for _, b := range blocks {
307			if b.Type == "output_text" && b.Text != "" {
308				texts = append(texts, b.Text)
309			}
310		}
311		return strings.Join(texts, "\n\n")
312	}
313	
314	// codexToolUseBlock builds a compact tool_use content block from a function_call.
315	func codexToolUseBlock(p codexPayload) map[string]json.RawMessage {
316		block := map[string]json.RawMessage{
317			"type": mustJSON(transcript.ContentTypeToolUse),
318			"name": mustJSON(p.Name),
319		}
320		if p.CallID != "" {
321			block["id"] = mustJSON(p.CallID)
322		}
323	
324		// Parse the arguments JSON string into a raw object for the "input" field.
325		var args json.RawMessage
326		if json.Unmarshal([]byte(p.Arguments), &args) == nil {
327			block["input"] = args
328		}
329	
330		return block
331	}
332	
333	// codexConsumeToolCall builds a tool_use block from a function_call or custom_tool_call,
334	// consuming any trailing token_count lines and the matching output line.
335	// The caller must advance i past the tool call line itself before calling this function,
336	// and must verify p.Type is a tool call type.
337	func codexConsumeToolCall(p codexPayload, lines []codexLine, i *int, inTok, outTok *int) map[string]json.RawMessage {
338		var tb map[string]json.RawMessage
339		var outputType string
340	
341		switch p.Type {
342		case codexTypeFunctionCall:
343			tb = codexToolUseBlock(p)
344			outputType = codexTypeFunctionCallOutput
345		case codexTypeCustomToolCall:
346			tb = codexCustomToolUseBlock(p)
347			outputType = codexTypeCustomToolCallOutput
348		default:
349			return nil
350		}
351	
352		for *i+1 < len(lines) && isCodexTokenCountLine(lines[*i+1]) {
353			*inTok, *outTok = codexTokenCount(lines[*i+1].Payload)
354			*i++
355		}
356	
357		if *i+1 < len(lines) {
358			callID, typ := codexCallIDAndType(lines[*i+1].Payload)
359			if typ == outputType && callID == p.CallID {
360				output := codexToolOutputText(lines[*i+1].Payload, outputType)
361				tb["result"] = buildToolResult(toolResultEntry{output: output})
362				*i++
363			}
364		}
365	
366		return tb
367	}
368	
369	// codexToolOutputText extracts the output text from a tool call output payload.
370	// For function_call_output, the output field is a plain string.
371	// For custom_tool_call_output, it is an object {"type":"text","text":"..."}.
372	func codexToolOutputText(payload json.RawMessage, outputType string) string {
373		if outputType == codexTypeCustomToolCallOutput {
374			return codexCustomOutputText(payload)
375		}
376		var p codexPayload
377		if json.Unmarshal(payload, &p) == nil {
378			return p.Output
379		}
380		return ""
381	}
382	
383	// codexCallIDAndType extracts just the type and call_id from a payload without
384	// failing on fields with unexpected types (e.g., custom_tool_call_output has an
385	// object "output" field that can't unmarshal into codexPayload.Output string).
386	func codexCallIDAndType(payload json.RawMessage) (callID, typ string) {
387		var p struct {
388			Type   string `json:"type"`
389			CallID string `json:"call_id"`
390		}
391		if json.Unmarshal(payload, &p) == nil {
392			return p.CallID, p.Type
393		}
394		return "", ""
395	}
396	
397	// codexCustomToolUseBlock builds a tool_use block from a custom_tool_call payload.
398	// Unlike function_call, the input is plain text (e.g., apply_patch content) rather
399	// than a JSON arguments string.
400	func codexCustomToolUseBlock(p codexPayload) map[string]json.RawMessage {
401		block := map[string]json.RawMessage{
402			"type": mustJSON(transcript.ContentTypeToolUse),
403			"name": mustJSON(p.Name),
404		}
405		if p.CallID != "" {
406			block["id"] = mustJSON(p.CallID)
407		}
408		if p.Input != "" {
409			if inputJSON, err := json.Marshal(map[string]string{"input": p.Input}); err == nil {
410				block["input"] = inputJSON
411			}
412		}
413		return block
414	}
415	
416	// codexCustomOutputText extracts the output text from a custom_tool_call_output payload.
417	// The output field is an object {"type":"text","text":"..."} rather than a plain string.
418	func codexCustomOutputText(payload json.RawMessage) string {
419		var p struct {
420			Output json.RawMessage `json:"output"`
421		}
422		if json.Unmarshal(payload, &p) != nil || p.Output == nil {
423			return ""
424		}
425		// Try as plain string first (for forward compatibility).
426		var s string
427		if json.Unmarshal(p.Output, &s) == nil {
428			return s
429		}
430		// Try as object with "text" field.
431		var obj struct {
432			Text string `json:"text"`
433		}
434		if json.Unmarshal(p.Output, &obj) == nil {
435			return obj.Text
436		}
437		return ""
438	}
439	
440	// mustJSON marshals v to JSON, panicking on error (only used for simple types).
441	func mustJSON(v interface{}) json.RawMessage {
442		b, err := json.Marshal(v)
443		if err != nil {
444			panic(fmt.Sprintf("compact: mustJSON: %v", err))
445		}
446		return b
447	}
448	
449	// codexBuildContent builds the compact content array from assistant text and
450	// optional tool_use blocks.
451	func codexBuildContent(text string, toolBlocks []map[string]json.RawMessage) json.RawMessage {
452		var content []map[string]json.RawMessage
453	
454		if text != "" {
455			content = append(content, map[string]json.RawMessage{
456				"type": mustJSON(transcript.ContentTypeText),
457				"text": mustJSON(text),
458			})
459		}
460		content = append(content, toolBlocks...)
461	
462		b, err := json.Marshal(content)
463		if err != nil {
464			return nil
465		}
466		return b
467	}
