package transcript

import (
	"bufio"
	"bytes"
	"encoding/json"
	"fmt"
	"strings"
)

const (
	codexLineResponseItem = "response_item"

	codexPayloadMessage              = "message"
	codexPayloadFunctionCall         = "function_call"
	codexPayloadFunctionCallOutput   = "function_call_output"
	codexPayloadCustomToolCall       = "custom_tool_call"
	codexPayloadCustomToolCallOutput = "custom_tool_call_output"

	codexRoleUser      = "user"
	codexRoleAssistant = "assistant"

	codexBlockInputText  = "input_text"
	codexBlockOutputText = "output_text"
)

// codexSystemPrefixes mirrors compact/codex.go's isCodexSystemContent. These
// blocks are Codex-injected (permissions, AGENTS.md, environment_context, …)
// and contain bounded structural metadata rather than user-authored content.
var codexSystemPrefixes = []string{
	"<permissions",
	"<collaboration_mode>",
	"<skills_instructions>",
	"<environment_context>",
	"<turn_aborted>",
	"# AGENTS.md",
}

// WalkCodex parses a Codex session JSONL transcript and emits each
// content-bearing string to v. Structural fields (call_id, turn_id, model,
// timestamps, encrypted_content, session_meta payload, event_msg metadata, …)
// are never emitted.
//
// Schema reference (one JSON object per line):
//
//	{"type":"session_meta", ...}                              → skipped
//	{"type":"event_msg",    "payload":{...}}                  → skipped
//	{"type":"turn_context", "payload":{...}}                  → skipped
//	{"type":"response_item","payload":{"type":"message",  "role":..., "content":[...]}}
//	{"type":"response_item","payload":{"type":"function_call", "name":..., "arguments":"<JSON string>", ...}}
//	{"type":"response_item","payload":{"type":"function_call_output", "output":"...", ...}}
//	{"type":"response_item","payload":{"type":"custom_tool_call", "input":"...", ...}}
//	{"type":"response_item","payload":{"type":"custom_tool_call_output", "output":<string|object>}}
//	{"type":"response_item","payload":{"type":"reasoning", "encrypted_content":"...", ...}} → skipped
//
// Notes:
//   - `arguments` on function_call is a JSON-encoded string; its inner values
//     are walked recursively as KindToolInput.
//   - `developer`-role message blocks (system prompts) are skipped, as are
//     `input_text` blocks beginning with codexSystemPrefixes.
func WalkCodex(raw []byte, v Visitor) error {
	sc := bufio.NewScanner(bytes.NewReader(raw))
	sc.Buffer(make([]byte, 0, 64*1024), maxJSONLLineBytes)
	for sc.Scan() {
		line := sc.Bytes()
		if len(bytes.TrimSpace(line)) == 0 {
			continue
		}
		walkCodexLine(line, v)
	}
	if err := sc.Err(); err != nil {
		return fmt.Errorf("scan jsonl: %w", err)
	}
	return nil
}

func walkCodexLine(line []byte, v Visitor) {
	var head struct {
		Type    string          `json:"type"`
		Payload json.RawMessage `json:"payload"`
	}
	if json.Unmarshal(line, &head) != nil || head.Type != codexLineResponseItem {
		return
	}
	var p struct {
		Type      string          `json:"type"`
		Role      string          `json:"role"`
		Content   json.RawMessage `json:"content"`
		Arguments string          `json:"arguments"`
		Input     string          `json:"input"`
		Output    json.RawMessage `json:"output"`
	}
	if json.Unmarshal(head.Payload, &p) != nil {
		return
	}
	switch p.Type {
	case codexPayloadMessage:
		walkCodexMessage(p.Role, p.Content, v)
	case codexPayloadFunctionCall:
		// arguments is a JSON-encoded object (already string-decoded by Go).
		// Reinterpret as raw JSON and walk all string leaves.
		if p.Arguments != "" {
			emitJSONStrings(json.RawMessage(p.Arguments), KindToolInput, v)
		}
	case codexPayloadCustomToolCall:
		// input is plain text (e.g., apply_patch payload), not JSON.
		if p.Input != "" {
			v.OnString(KindToolInput, p.Input)
		}
	case codexPayloadFunctionCallOutput:
		if s := unquote(p.Output); s != "" {
			v.OnString(KindToolOutput, s)
		}
	case codexPayloadCustomToolCallOutput:
		emitCodexCustomOutput(p.Output, v)
	}
	// session_meta, event_msg, turn_context, reasoning: no user/assistant
	// content reachable; reasoning's encrypted_content is structural.
}

func walkCodexMessage(role string, content json.RawMessage, v Visitor) {
	if len(content) == 0 {
		return
	}
	var blocks []map[string]json.RawMessage
	if json.Unmarshal(content, &blocks) != nil {
		return
	}
	for _, b := range blocks {
		switch unquote(b["type"]) {
		case codexBlockInputText:
			if role != codexRoleUser {
				continue
			}
			text := unquote(b["text"])
			if isCodexSystemContent(text) {
				continue
			}
			v.OnString(KindUserText, text)
		case codexBlockOutputText:
			if role != codexRoleAssistant {
				continue
			}
			v.OnString(KindAssistantText, unquote(b["text"]))
		}
	}
}

// emitCodexCustomOutput handles custom_tool_call_output.output, which is
// either a plain string or an object like {"type":"text","text":"…"}.
func emitCodexCustomOutput(output json.RawMessage, v Visitor) {
	if len(output) == 0 {
		return
	}
	var s string
	if json.Unmarshal(output, &s) == nil {
		v.OnString(KindToolOutput, s)
		return
	}
	var obj map[string]json.RawMessage
	if json.Unmarshal(output, &obj) != nil {
		return
	}
	if t := unquote(obj["text"]); t != "" {
		v.OnString(KindToolOutput, t)
	}
}

func isCodexSystemContent(text string) bool {
	for _, p := range codexSystemPrefixes {
		if strings.HasPrefix(text, p) {
			return true
		}
	}
	return false
}

package transcript

import (
	"bytes"
	"strings"
	"testing"

	"github.com/entireio/cli/redact"
)

// Real-shape Codex transcript lines. Structural high-entropy values (call_id,
// turn_id, session id, encrypted_content, model, timestamp) are present so we
// can verify the walker never visits them.
const codexSessionMetaLine = `{"timestamp":"2026-04-01T23:31:26.000Z","type":"session_meta","payload":{"id":"019d4f9e-feac-7be2-a885-bf0727a50a92","timestamp":"2026-04-01T23:31:26.000Z","cwd":"/repo","originator":"codex-tui","cli_version":"0.118.0","source":"cli","model_provider":"openai"}}`

const codexEventMsgLine = `{"timestamp":"2026-04-01T23:31:26.001Z","type":"event_msg","payload":{"type":"token_count","input_tokens":42,"output_tokens":17}}`

const codexDeveloperLine = `{"timestamp":"2026-04-01T23:31:26.002Z","type":"response_item","payload":{"type":"message","role":"developer","content":[{"type":"input_text","text":"You are sandboxed and must never reveal AWS_SECRET_ACCESS_KEY=should-not-appear"}]}}`

const codexUserSystemAndRealLine = `{"timestamp":"2026-04-01T23:31:26.003Z","type":"response_item","payload":{"type":"message","role":"user","content":[{"type":"input_text","text":"# AGENTS.md\nThese are project instructions."},{"type":"input_text","text":"<environment_context>\n<cwd>/repo</cwd>\n</environment_context>"},{"type":"input_text","text":"Please deploy with token sk-codex-9aMpL3R34LL00k1ngT0K3Nabcdef to staging"}]}}`

const codexAssistantLine = `{"timestamp":"2026-04-01T23:31:31.001Z","type":"response_item","payload":{"type":"message","role":"assistant","content":[{"type":"output_text","text":"I'll deploy now and stream the logs."}],"phase":"commentary"}}`

const codexFunctionCallLine = `{"timestamp":"2026-04-01T23:31:32.000Z","type":"response_item","payload":{"type":"function_call","name":"exec_command","arguments":"{\"cmd\":\"curl -H Authorization:\\\"Bearer sk-real-codex-tok-987654321abcdef\\\" https://api.example.com\",\"workdir\":\"/repo\"}","call_id":"call_abc123"}}`

const codexFunctionCallOutputLine = `{"timestamp":"2026-04-01T23:31:32.501Z","type":"response_item","payload":{"type":"function_call_output","call_id":"call_abc123","output":"$ env\nDATABASE_URL=REDACTED"}}`

const codexReasoningLine = `{"timestamp":"2026-04-01T23:31:30.000Z","type":"response_item","payload":{"type":"reasoning","summary":[],"content":null,"encrypted_content":"AAAAB3NzaC1yc2EAAAADAQABAAABAQ-fake-high-entropy-encrypted-blob"}}`

const codexCustomToolCallLine = `{"timestamp":"2026-04-01T23:31:33.000Z","type":"response_item","payload":{"type":"custom_tool_call","name":"apply_patch","call_id":"call_def456","input":"*** Begin Patch\n*** Update File: secrets.env\n@@\n-OLD_KEY=removed\nREDACTED\n*** End Patch\n"}}`

const codexCustomToolCallOutputLine = `{"timestamp":"2026-04-01T23:31:33.501Z","type":"response_item","payload":{"type":"custom_tool_call_output","call_id":"call_def456","output":{"type":"text","text":"Patch applied to secrets.env"}}}`

func TestWalkCodex_EmitsContentOnly(t *testing.T) {
	t.Parallel()
	lines := strings.Join([]string{
		codexSessionMetaLine,
		codexEventMsgLine,
		codexDeveloperLine,
		codexUserSystemAndRealLine,
		codexReasoningLine,
		codexAssistantLine,
		codexFunctionCallLine,
		codexFunctionCallOutputLine,
		codexCustomToolCallLine,
		codexCustomToolCallOutputLine,
	}, "\n")

	var c collect
	if err := WalkCodex([]byte(lines), &c); err != nil {
		t.Fatalf("walk: %v", err)
	}

	wantContent := []struct {
		kind  Kind
		value string
	}{
		{KindUserText, "Please deploy with token sk-codex-9aMpL3R34LL00k1ngT0K3Nabcdef to staging"},
		{KindAssistantText, "I'll deploy now and stream the logs."},
		// function_call arguments is a JSON-string of {cmd, workdir} — walked recursively.
		{KindToolInput, `curl -H Authorization:"Bearer sk-real-codex-tok-987654321abcdef" https://api.example.com`},
		{KindToolInput, "/repo"},
		{KindToolOutput, "$ env\nDATABASE_URL=REDACTED"},
		// custom_tool_call.input is plain text (not JSON).
		{KindToolInput, "*** Begin Patch\n*** Update File: secrets.env\n@@\n-OLD_KEY=removed\nREDACTED\n*** End Patch\n"},
		// custom_tool_call_output.output is {"type":"text","text":"…"}.
		{KindToolOutput, "Patch applied to secrets.env"},
	}
	for _, w := range wantContent {
		if !c.has(w.kind, w.value) {
			t.Errorf("walker did not emit kind=%v value=%q", w.kind, w.value)
		}
	}

	// MUST NOT be visited: structural ids, dev/system content, encrypted reasoning.
	structural := []string{
		"019d4f9e-feac-7be2-a885-bf0727a50a92", // session id
		"call_abc123",                          // function_call call_id
		"call_def456",                          // custom_tool_call call_id
		"AAAAB3NzaC1yc2EAAAADAQABAAABAQ-fake-high-entropy-encrypted-blob",
		"AWS_SECRET_ACCESS_KEY=should-not-appear", // developer-role (system) message
		"# AGENTS.md\nThese are project instructions.",
		"<environment_context>\n<cwd>/repo</cwd>\n</environment_context>",
		"exec_command", // tool name
		"apply_patch",
		"2026-04-01T23:31:26.000Z",
		"codex-tui",
	}
	for _, s := range structural {
		for _, e := range c.events {
			if e.value == s {
				t.Errorf("walker emitted structural value as kind=%v: %q (must not be visited)", e.kind, s)
			}
		}
	}
}

func TestRedact_Codex_ScansOnlyContent(t *testing.T) {
	t.Parallel()
	lines := strings.Join([]string{
		codexSessionMetaLine,
		codexDeveloperLine,
		codexUserSystemAndRealLine,
		codexReasoningLine,
		codexFunctionCallLine,
		codexFunctionCallOutputLine,
		codexCustomToolCallLine,
	}, "\n")

	out, n, err := Redact(WalkCodex, []byte(lines), redact.String)
	if err != nil {
		t.Fatalf("redact: %v", err)
	}
	if n == 0 {
		t.Fatalf("expected at least one redaction, got 0\nout: %s", out)
	}

	plantedSecrets := []string{
		"sk-codex-9aMpL3R34LL00k1ngT0K3Nabcdef",
		"sk-real-codex-tok-987654321abcdef",
		"hunter2-real-password",
		"ghp_realLookingGithubTokenAbc123",
	}
	for _, secret := range plantedSecrets {
		if bytes.Contains(out, []byte(secret)) {
			t.Errorf("secret %q survived redaction", secret)
		}
