package transcript

import (
	"bufio"
	"bytes"
	"encoding/json"
	"fmt"
)

// maxJSONLLineBytes matches the 10MB buffer the existing compactor uses
// (compact/codex.go) — agent transcript lines can exceed the default 64KB.
const maxJSONLLineBytes = 10 * 1024 * 1024

// scanJSONL invokes lineFn for each non-blank JSONL line in raw with v as
// the active visitor.
func scanJSONL(raw []byte, v Visitor, lineFn func([]byte, Visitor)) error {
	sc := bufio.NewScanner(bytes.NewReader(raw))
	sc.Buffer(make([]byte, 0, 64*1024), maxJSONLLineBytes)
	for sc.Scan() {
		line := sc.Bytes()
		if len(bytes.TrimSpace(line)) == 0 {
			continue
		}
		lineFn(line, v)
	}
	if err := sc.Err(); err != nil {
		return fmt.Errorf("scan jsonl: %w", err)
	}
	return nil
}

// walkBlocks parses a JSON array of typed content blocks and dispatches each
// to the per-role handler. Returns silently on malformed input.
func walkBlocks(content json.RawMessage, v Visitor, dispatch func(map[string]json.RawMessage, Visitor)) {
	if len(content) == 0 {
		return
	}
	var blocks []map[string]json.RawMessage
	if json.Unmarshal(content, &blocks) != nil {
		return
	}
	for _, b := range blocks {
		dispatch(b, v)
	}
}

func unquote(raw json.RawMessage) string {
	var s string
	if json.Unmarshal(raw, &s) == nil {
		return s
	}
	return ""
}

package transcript

import (
	"encoding/json"
)

const (
	// Top-level line types in Claude Code's session JSONL.
	claudeTypeUser      = "user"
	claudeTypeHuman     = "human" // legacy alias for user
	claudeTypeAssistant = "assistant"

	// Content block types appearing inside message.content arrays.
	claudeBlockText             = "text"
	claudeBlockToolUse          = "tool_use"
	claudeBlockToolResult       = "tool_result"
	claudeBlockThinking         = "thinking"
	claudeBlockRedactedThinking = "redacted_thinking"
)

// WalkClaudeCode parses a Claude Code session JSONL transcript and emits each
// content-bearing string to v. Structural fields (uuid, promptId, sessionId,
// requestId, signatures, model, timestamps, cwd, gitBranch, tool ids, …) are
// never emitted.
//
// Schema reference (one JSON object per line):
//
//	{"type":"user","message":{"role":"user","content": "..." | [block,...]}, ...}
//	{"type":"assistant","message":{"id":"msg_…","content":[block,...]}, ...}
//
// User content blocks: text → KindUserText, tool_result → KindToolOutput,
// image → skipped. Assistant content blocks: text/thinking → KindAssistantText,
// tool_use → recursive scan of input as KindToolInput, redacted_thinking → skipped.
func WalkClaudeCode(raw []byte, v Visitor) error {
	return scanJSONL(raw, v, walkClaudeCodeLine)
}

func walkClaudeCodeLine(line []byte, v Visitor) {
	var head struct {
		Type    string          `json:"type"`
		Message json.RawMessage `json:"message"`
	}
	if json.Unmarshal(line, &head) != nil {
		return
	}
	switch head.Type {
	case claudeTypeUser, claudeTypeHuman:
		walkClaudeMessage(head.Message, v, KindUserText, dispatchUserBlock)
	case claudeTypeAssistant:
		walkClaudeMessage(head.Message, v, KindAssistantText, dispatchAssistantBlock)
	}
}

// walkClaudeMessage parses message.content (string OR array of typed blocks).
// A bare-string content is emitted directly as bareKind; typed blocks are
// dispatched to the per-role handler.
func walkClaudeMessage(msg json.RawMessage, v Visitor, bareKind Kind, dispatch func(map[string]json.RawMessage, Visitor)) {
	if len(msg) == 0 {
		return
	}
	var envelope struct {
		Content json.RawMessage `json:"content"`
	}
	if json.Unmarshal(msg, &envelope) != nil {
		return
	}
	var asString string
	if json.Unmarshal(envelope.Content, &asString) == nil {
		v.OnString(bareKind, asString)
		return
	}
	walkBlocks(envelope.Content, v, dispatch)
}

func dispatchUserBlock(b map[string]json.RawMessage, v Visitor) {
	switch unquote(b["type"]) {
	case claudeBlockText:
		v.OnString(KindUserText, unquote(b["text"]))
	case claudeBlockToolResult:
		emitToolResultContent(b["content"], v)
	}
}

func dispatchAssistantBlock(b map[string]json.RawMessage, v Visitor) {
	switch unquote(b["type"]) {
	case claudeBlockText:
		v.OnString(KindAssistantText, unquote(b["text"]))
	case claudeBlockThinking:
		// Emit only the thinking text. The neighboring `signature` field is a
		// high-entropy structural value the generic redactor false-positives
		// on — keeping it unvisited is the structural fix.
		v.OnString(KindAssistantText, unquote(b["thinking"]))
	case claudeBlockToolUse:
		emitJSONStrings(b["input"], KindToolInput, v)
	case claudeBlockRedactedThinking:
		// Already redacted by the provider.
	}
}

func emitToolResultContent(raw json.RawMessage, v Visitor) {
	if len(raw) == 0 {
		return
	}
	var asString string
	if json.Unmarshal(raw, &asString) == nil {
		v.OnString(KindToolOutput, asString)
		return
	}
	var blocks []map[string]json.RawMessage
	if json.Unmarshal(raw, &blocks) != nil {
		return
	}
	for _, b := range blocks {
		if unquote(b["type"]) == claudeBlockText {
			v.OnString(KindToolOutput, unquote(b["text"]))
		}
	}
}

// emitJSONStrings recursively walks any JSON value and emits every string leaf
// under kind. Used for tool_use.input — arbitrary tool-defined JSON we can't
// enumerate schemas for.
func emitJSONStrings(raw json.RawMessage, kind Kind, v Visitor) {
	if len(raw) == 0 {
		return
	}
	var node interface{}
	if json.Unmarshal(raw, &node) != nil {
		return
	}
	walkAny(node, kind, v)
}

func walkAny(node any, kind Kind, v Visitor) {
	switch t := node.(type) {
	case string:
		v.OnString(kind, t)
	case []any:
		for _, child := range t {
			walkAny(child, kind, v)
		}
	case map[string]any:
		for _, child := range t {
			walkAny(child, kind, v)
		}
	}
}

package transcript

import (
	"encoding/json"
	"strings"
)

const (
	codexLineResponseItem = "response_item"

	codexPayloadMessage              = "message"
	codexPayloadFunctionCall         = "function_call"
	codexPayloadFunctionCallOutput   = "function_call_output"
	codexPayloadCustomToolCall       = "custom_tool_call"
	codexPayloadCustomToolCallOutput = "custom_tool_call_output"

	codexRoleUser      = "user"
	codexRoleAssistant = "assistant"

	codexBlockInputText  = "input_text"
	codexBlockOutputText = "output_text"
)

// codexSystemPrefixes mirrors compact/codex.go's isCodexSystemContent. Blocks
// starting with these are Codex-injected metadata (permissions, AGENTS.md,
// environment_context, …) rather than user-authored content.
var codexSystemPrefixes = []string{
	"<permissions",
	"<collaboration_mode>",
	"<skills_instructions>",
	"<environment_context>",
	"<turn_aborted>",
	"# AGENTS.md",
}

// WalkCodex parses a Codex session JSONL transcript and emits each
// content-bearing string to v. Structural fields (call_id, turn_id, model,
// timestamps, encrypted_content, session_meta payload, event_msg metadata, …)
// are never emitted.
//
// Schema (one JSON object per line):
//
//	{"type":"session_meta", ...}                              → skipped
//	{"type":"event_msg",    "payload":{...}}                  → skipped
//	{"type":"turn_context", "payload":{...}}                  → skipped
//	{"type":"response_item","payload":{"type":"message",  "role":..., "content":[...]}}
//	{"type":"response_item","payload":{"type":"function_call", "arguments":"<JSON string>", ...}}
//	{"type":"response_item","payload":{"type":"function_call_output", "output":"...", ...}}
//	{"type":"response_item","payload":{"type":"custom_tool_call", "input":"...", ...}}
//	{"type":"response_item","payload":{"type":"custom_tool_call_output", "output":<string|object>}}
//	{"type":"response_item","payload":{"type":"reasoning", "encrypted_content":"...", ...}} → skipped
//
// developer-role messages and input_text blocks beginning with
// codexSystemPrefixes are skipped.
func WalkCodex(raw []byte, v Visitor) error {
	return scanJSONL(raw, v, walkCodexLine)
}

func walkCodexLine(line []byte, v Visitor) {
	var head struct {
		Type    string          `json:"type"`
		Payload json.RawMessage `json:"payload"`
	}
	if json.Unmarshal(line, &head) != nil || head.Type != codexLineResponseItem {
		return
	}
	var p struct {
		Type      string          `json:"type"`
		Role      string          `json:"role"`
		Content   json.RawMessage `json:"content"`
		Arguments string          `json:"arguments"`
		Input     string          `json:"input"`
		Output    json.RawMessage `json:"output"`
	}
	if json.Unmarshal(head.Payload, &p) != nil {
		return
	}
	switch p.Type {
	case codexPayloadMessage:
		switch p.Role {
		case codexRoleUser:
			walkBlocks(p.Content, v, dispatchCodexUserBlock)
		case codexRoleAssistant:
			walkBlocks(p.Content, v, dispatchCodexAssistantBlock)
		}
	case codexPayloadFunctionCall:
		// arguments is a JSON-encoded string nesting another JSON object, so
		// emit it whole — the redactor's single-level re-encoding then
		// matches the outer-level escaping in raw bytes by construction.
		if p.Arguments != "" {
			v.OnString(KindToolInput, p.Arguments)
		}
	case codexPayloadCustomToolCall:
		// input is plain text (e.g., apply_patch payload), not JSON.
		if p.Input != "" {
			v.OnString(KindToolInput, p.Input)
		}
	case codexPayloadFunctionCallOutput:
		if s := unquote(p.Output); s != "" {
			v.OnString(KindToolOutput, s)
		}
	case codexPayloadCustomToolCallOutput:
		emitCodexCustomOutput(p.Output, v)
	}
}

func dispatchCodexUserBlock(b map[string]json.RawMessage, v Visitor) {
	if unquote(b["type"]) != codexBlockInputText {
		return
	}
	text := unquote(b["text"])
	if isCodexSystemContent(text) {
		return
	}
	v.OnString(KindUserText, text)
}

func dispatchCodexAssistantBlock(b map[string]json.RawMessage, v Visitor) {
	if unquote(b["type"]) != codexBlockOutputText {
		return
	}
	v.OnString(KindAssistantText, unquote(b["text"]))
}

// emitCodexCustomOutput handles custom_tool_call_output.output, which is
// either a plain string or an object like {"type":"text","text":"…"}.
func emitCodexCustomOutput(output json.RawMessage, v Visitor) {
	if len(output) == 0 {
		return
	}
	var s string
	if json.Unmarshal(output, &s) == nil {
		v.OnString(KindToolOutput, s)
		return
	}
	var obj map[string]json.RawMessage
	if json.Unmarshal(output, &obj) != nil {
		return
	}
	if t := unquote(obj["text"]); t != "" {
		v.OnString(KindToolOutput, t)
	}
}

func isCodexSystemContent(text string) bool {
	for _, p := range codexSystemPrefixes {
		if strings.HasPrefix(text, p) {
			return true
		}
	}
	return false
}

