// redactNativeTranscript redacts a raw agent-native transcript. When the
// agent has a TranscriptWalker (content-targeted redaction with no
// false-positives on structural fields like uuids/signatures/paths), it is
// used. Otherwise we fall back to the generic redact.JSONLBytes pass.
//
// Per-agent rollout: implementing a walker for an agent flips that agent
// onto the new path; no flag, no settings, no opt-in.
func redactNativeTranscript(raw []byte, ag agent.Agent) (redact.RedactedBytes, error) {
	if tw, ok := agent.AsTranscriptWalker(ag); ok {
		out, _, err := transcript.Redact(tw.WalkTranscript, raw, redact.String)
		if err != nil {
			return redact.RedactedBytes{}, fmt.Errorf("walker redact: %w", err)
		}
		return redact.AlreadyRedacted(out), nil
	}
	return redact.JSONLBytes(raw)
}

