package strategy

import (
	"bytes"
	"errors"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/claudecode"
	"github.com/entireio/cli/cmd/entire/cli/agent/opencode"
	"github.com/entireio/cli/redact"
)

// A Claude Code session line with a planted secret in user text plus a
// high-entropy structural uuid that the generic redactor would false-positive on.
const redactHelperFixture = `{"parentUuid":"206230ce-3c3a-4668-8b27-b29120637230","type":"user","message":{"role":"user","content":"please run REDACTED against staging"},"uuid":"55d2b925-6228-4ab1-9a5f-9c31fb9f4a29","sessionId":"8b89dece-0f9b-4965-8436-fcec80f5ea06"}`

func TestRedactNativeTranscript_WalkerPath_RedactsContentPreservesStructural(t *testing.T) {
	t.Parallel()

	out, err := redactNativeTranscript([]byte(redactHelperFixture), claudecode.NewClaudeCodeAgent())
	if err != nil {
		t.Fatalf("redactNativeTranscript: %v", err)
	}
	if bytes.Contains(out.Bytes(), []byte("REDACTED")) {
		t.Error("planted secret survived walker-path redaction")
	}
	// Structural uuids must remain — proof the walker isolated them from the scanner.
	for _, id := range []string{
		"206230ce-3c3a-4668-8b27-b29120637230",
		"55d2b925-6228-4ab1-9a5f-9c31fb9f4a29",
		"8b89dece-0f9b-4965-8436-fcec80f5ea06",
	} {
		if !bytes.Contains(out.Bytes(), []byte(id)) {
			t.Errorf("structural id %q was redacted on the walker path", id)
		}
	}
}

func TestRedactNativeTranscript_FallbackPath_DispatchesToJSONLBytesSeam(t *testing.T) { //nolint:paralleltest // mutates package-level seam
	var called bool
	original := redactSessionJSONLBytes
	redactSessionJSONLBytes = func(raw []byte) (redact.RedactedBytes, error) {
		called = true
		return original(raw)
	}
	t.Cleanup(func() { redactSessionJSONLBytes = original })

	// OpenCode has no TranscriptWalker yet → fallback path expected.
	if _, err := redactNativeTranscript([]byte(redactHelperFixture), opencode.NewOpenCodeAgent()); err != nil {
		t.Fatalf("redactNativeTranscript: %v", err)
	}
	if !called {
		t.Error("fallback path must dispatch through the redactSessionJSONLBytes seam")
	}
}

func TestRedactNativeTranscript_NilAgent_FallsBack(t *testing.T) { //nolint:paralleltest // mutates package-level seam
	var called bool
	original := redactSessionJSONLBytes
	redactSessionJSONLBytes = func(raw []byte) (redact.RedactedBytes, error) {
		called = true
		return original(raw)
	}
	t.Cleanup(func() { redactSessionJSONLBytes = original })

	if _, err := redactNativeTranscript([]byte(redactHelperFixture), nil); err != nil {
		t.Fatalf("redactNativeTranscript: %v", err)
	}
	if !called {
		t.Error("nil agent must fall back to the redactSessionJSONLBytes seam")
	}
}

func TestRedactNativeTranscript_WalkerErrorPropagates(t *testing.T) { //nolint:paralleltest // mutates package-level seam
	original := redactNativeTranscript
	redactNativeTranscript = func([]byte, agent.Agent) (redact.RedactedBytes, error) {
		return redact.RedactedBytes{}, errors.New("forced walker failure")
	}
	t.Cleanup(func() { redactNativeTranscript = original })

	_, err := redactNativeTranscript([]byte(redactHelperFixture), claudecode.NewClaudeCodeAgent())
	if err == nil {
		t.Fatal("expected forced walker failure to surface")
	}
}
